import{_ as e,c as o,o as t,a3 as a}from"./chunks/framework.DpFyhY0e.js";const f=JSON.parse('{"title":"Components","description":"","frontmatter":{},"headers":[],"relativePath":"components.md","filePath":"components.md"}'),s={name:"components.md"},n=a('<h1 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h1><p>Components allow you to create dependency relationships between different attribute stock items. Normally, when a product has multiple stock items associated with it their quantities are used in parallel. But with components you can use stock in series, i.e. one after the other.</p><p>We&#39;ve kept this functionality as generic as possible to allow for various use cases, such as:</p><ul><li>Stock of other stock items, e.g. parts/ingredients of assembled inventory or product variants.</li><li>Batches of stock that need to be used in sequence, e.g. <code>batch B</code> is used only once <code>batch A</code> has been used up.</li><li>The same stock from different suppliers, e.g. with a relationship like <code>A &gt; B &gt; C</code>, if supplier <code>A</code> has no stock left, then <code>B</code> or <code>C</code> will be used if they have stock. Product availability is <code>A + B + C</code>.</li></ul><h2 id="how-does-it-work" tabindex="-1">How does it work? <a class="header-anchor" href="#how-does-it-work" aria-label="Permalink to &quot;How does it work?&quot;">​</a></h2><p>Let&#39;s use a simple example. Imagine you design and sell painted candles. You have 100 stock of plain candles, 10 stock of painted candles with design A and 10 stock of design B.</p><p>You can set your <code>plain candle</code> stock as a <a href="./terminology#parent-child-component">child component</a> of your <code>painted candle A</code> and <code>painted candle B</code> stock. The effective available stock of <code>painted candle A</code> is now 110, because you can always make more painted candles from your plain candle stock.</p><p>You can additionally sell your <code>plain candles</code> as its own product, or you can simply use them as component stock. In the latter case, you don&#39;t need to add any attribute <a href="./terminology#match-rule">match rules</a> to the stock item. Component stock will always apply to its parent stock regardless of match rules or settings like <a href="./attribute-stock#settings">internal stock</a>.</p><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2>',9),c=[n];function i(d,l,r,p,h,u){return t(),o("div",null,c)}const k=e(s,[["render",i]]);export{f as __pageData,k as default};
